import React, { useState, useEffect } from "react";
import Sidebar from "../../components/Sidebar_p-a";
import HeaderPanel from "../../components/HeaderPanel";
import "../../components/admin.css"; 

export default function Entradas() {
    return (
        <div className="dashboard-layout">
            <Sidebar />
            <main className="contenido">
                <HeaderPanel />

                {/* Contenedor de mensajes */}
                {mensaje && (
                    <div className={`mensaje ${mensaje.type}`}>
                        {mensaje.text}
                    </div>
                )}

                <section className="cuadro-blanco form-producto">

                    <form className="formulario" onSubmit={handleSubmit}>

                        {/* ID Producto (Campo clave) */}
                        <div className="campo">
                            <label htmlFor="id_producto">ID del Producto</label>
                            <input 
                                type="number" 
                                id="id_producto" 
                                name="id_producto" 
                                placeholder="Ingrese el ID del producto" 
                                value={formData.id_producto}
                                onChange={handleChange}
                                required 
                            />
                        </div>

                        {/* Nombre del Producto (se rellena automáticamente) */}
                        <div className="campo">
                            <label htmlFor="nom_producto">Nombre del Producto</label>
                            <input 
                                type="text" 
                                id="nom_producto" 
                                name="nom_producto" 
                                placeholder="Ejemplo: Sábana Paw Patrol" 
                                value={formData.nom_producto}
                                onChange={handleChange}
                                readOnly={!!formData.stock_actual && !mensaje?.text.includes('no encontrado')} // Desactivar si existe
                                required 
                            />
                        </div>
                        {/* ... (resto de los campos del formulario usando value={formData.nombre_campo} y onChange={handleChange}) ... */}

                        {/* Stock Actual (solo lectura) */}
                        <div className="campo">
                            <label htmlFor="stock_actual">Stock Actual (Sistema)</label>
                            <input 
                                type="text" 
                                id="stock_actual" 
                                name="stock_actual" 
                                placeholder="Stock actual del producto" 
                                value={formData.stock_actual}
                                readOnly={true} 
                            />
                        </div>

                        {/* Cantidad ingresada (Nuevo stock a sumar) */}
                        <div className="campo">
                            <label htmlFor="cantidad_ingresada">Cantidad ingresada</label>
                            <input 
                                type="number" 
                                id="cantidad_ingresada" 
                                name="cantidad_ingresada" 
                                placeholder="Cantidad de unidades que entran" 
                                value={formData.cantidad_ingresada}
                                onChange={handleChange}
                                required 
                            />
                        </div>

                        {/* Proveedor */}
                        <div className="campo">
                            <label htmlFor="proveedor">Proveedor</label>
                            <input 
                                type="text" 
                                id="proveedor" 
                                name="proveedor" 
                                placeholder="Nombre del proveedor" 
                                value={formData.proveedor}
                                onChange={handleChange}
                                required 
                            />
                        </div>

                        {/* ... (otros campos como fecha, observaciones) ... */}

                        {/* Botones de acción */}
                        <div className="botones">
                            <button type="submit" className="btn-guardar">
                                <i className="fa-solid fa-floppy-disk"></i> Guardar
                            </button>
                            <button type="reset" className="btn-cancelar">
                                <i className="fa-solid fa-xmark"></i> Cancelar
                            </button>
                        </div>
                    </form>
                </section>
            </main>
        </div>
    );
}
